css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:88px 0}
.dark{background:var(--k);color:#fff}.dark2{background:var(--k2);color:#fff}.grey{background:var(--g)}
.dark p,.dark2 p{color:var(--dmute)}
.sh{max-width:640px;margin-bottom:44px}
.sh h2{font-size:clamp(28px,4vw,42px)}
.sh p{margin-top:14px;color:var(--mute);font-size:17px}
.dark .sh p,.dark2 .sh p{color:var(--dmute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}
.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
nav{position:sticky;top:0;z-index:20;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}
nav .btn{padding:10px 18px;font-size:14px}
/* phones */
.ph{--pw:210px;width:var(--pw);aspect-ratio:9/18.5;background:#1a1a1e;border:2px solid #34343a;border-radius:34px;padding:8px;box-shadow:0 24px 50px #000a;position:relative;flex:none}
.sc{height:100%;background:var(--w);border-radius:26px;overflow:hidden;color:var(--ink);padding:2.6em 1.1em 1em;font-size:calc(var(--pw)/20);display:flex;flex-direction:column;gap:.7em;position:relative;line-height:1.35}
.sc::before{content:"";position:absolute;top:.8em;left:50%;transform:translateX(-50%);width:5em;height:1.3em;border-radius:1em;background:#111}
.sc h5{font-size:1.35em}
.sc .chips{display:flex;gap:.5em}.chips i{font-style:normal;flex:1;text-align:center;padding:.5em 0;border-radius:.8em;background:var(--g);font-weight:500}.chips i.on{background:var(--k);color:var(--l)}
.it{display:flex;justify-content:space-between;align-items:center;gap:.5em;padding:.9em;border:1px solid var(--line);border-radius:1em;background:#fff}
.it span{color:var(--mute);font-size:.9em}.it.on{border-color:var(--k);box-shadow:0 0 0 .2em #C7FF3F88}
.bt{margin-top:auto;background:var(--k);color:#fff;text-align:center;padding:.95em;border-radius:99px;font-weight:600}
.cd{background:var(--k);color:#fff;border-radius:1.1em;padding:1em}.cd span{display:block;color:#aaa;font-size:.9em}.cd b{font:600 1.15em Sora}
.g4{display:grid;grid-template-columns:repeat(4,1fr);gap:.6em;text-align:center;font-size:.85em;color:var(--mute)}
.g4 i{display:block;aspect-ratio:1;border-radius:.9em;background:var(--g);margin-bottom:.3em}.g4 i:first-child{background:var(--l)}
.tab{margin-top:auto;display:flex;justify-content:space-around;padding-top:.7em;border-top:1px solid var(--line)}.tab i{width:1.3em;height:1.3em;border-radius:50%;background:#d6d7d3}.tab i:first-child{background:var(--k)}
.map{height:8.5em;border-radius:1em;background:linear-gradient(135deg,#e9ebe6,#dcdfd8);position:relative}
.map::after{content:"";position:absolute;left:30%;top:40%;width:1.2em;height:1.2em;border-radius:50%;background:var(--k);box-shadow:0 0 0 .4em #C7FF3F}
.stp{display:flex;align-items:center;gap:.7em;color:var(--mute)}.stp::before{content:"";width:.9em;height:.9em;border-radius:50%;border:2px solid #c9cac6;flex:none}
.stp.d::before{background:var(--k);border-color:var(--k)}.stp.on{color:var(--ink);font-weight:600}.stp.on::before{background:var(--l);border-color:var(--k)}
.im{height:6em;border-radius:1em;background:linear-gradient(135deg,#2a2a2e,#111);position:relative}.im.lt{background:linear-gradient(135deg,#dcdfd8,#c8ccc3)}
.im b{position:absolute;left:.7em;bottom:.6em;color:#fff;font-size:1em;font-weight:600}
/* hero */
.hero{padding:72px 0 88px;overflow:hidden}
.hero .wrap{display:grid;grid-template-columns:1fr 1.05fr;gap:40px;align-items:center}
.lab{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;color:var(--l);margin-bottom:22px}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.hero h1{font-size:clamp(46px,7.4vw,96px);line-height:.96;letter-spacing:-.04em}
.hero .sub{margin:24px 0 32px;font-size:clamp(17px,2vw,19px);max-width:470px;color:#d6d6da}
.stage{position:relative;height:500px}
.stage .ph{position:absolute}
.p1{left:0;top:70px;transform:rotate(-4deg)}.p2{left:50%;margin-left:-110px;top:0;--pw:220px;z-index:2}.p3{right:0;top:80px;transform:rotate(4deg)}
.cap{margin-top:14px;font-size:13px;color:var(--dmute)}
/* outcomes */
.vals{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.val{background:#fff;border:1px solid var(--line);border-radius:20px;padding:28px}
.val .ic{width:46px;height:46px;border-radius:12px;background:var(--k);display:grid;place-items:center;margin-bottom:22px}
.val .ic svg{width:22px;height:22px;stroke:var(--l);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.val h3{font-size:19px;margin-bottom:10px}.val p{color:var(--mute);font-size:15px}
/* bento */
.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}
.bc{border-radius:22px;padding:30px;background:#fff;border:1px solid var(--line);position:relative;overflow:hidden}
.bc h3{font-size:21px;margin-bottom:10px}.bc p{color:var(--mute);max-width:420px;font-size:15.5px}
.bc ul{margin:16px 0 0;padding:0;list-style:none;display:flex;flex-wrap:wrap;gap:8px}
.bc li{font-size:13px;padding:6px 12px;border-radius:99px;background:var(--g)}
.s4{grid-column:span 4}.s2{grid-column:span 2}
.bc.dk{background:var(--k);border-color:var(--k);color:#fff;min-height:270px}.bc.dk p{color:var(--dmute)}.bc.dk li{background:#1c1c20;color:#d8d8dc}
.bc .tag{display:inline-block;font:600 12px Inter;color:var(--k);background:var(--l);padding:5px 12px;border-radius:99px;margin-bottom:16px}
.two{display:flex;gap:14px;margin-top:24px}.two b{width:90px;height:110px;border-radius:16px;border:1px solid var(--dline);background:#16161a}.two b:first-child{border-color:var(--l)}
/* journey */
.jr{display:grid;grid-template-columns:repeat(7,1fr);position:relative;counter-reset:s}
.st{padding:0 10px 0 0;position:relative;counter-increment:s}
.st .dot{width:38px;height:38px;border-radius:50%;background:var(--k2);border:2px solid var(--dline);display:grid;place-items:center;margin-bottom:16px;position:relative;z-index:1;font:600 13px Sora;color:var(--l)}
.st .dot::before{content:counter(s)}
.st::after{content:"";position:absolute;left:46px;right:6px;top:18px;height:2px;background:linear-gradient(90deg,var(--l),#2a2a2e)}
.st:last-child::after{display:none}
.st h4{font-size:16px;margin-bottom:6px;color:#fff}.st p{font-size:13.5px}
/* industries */
.ind{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.id{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;transition:border-color .2s}
.id:hover{border-color:var(--k)}
.id h3{font-size:18px;margin-bottom:8px}.id p{font-size:14.5px;color:var(--mute)}
.id.more{background:var(--k);border-color:var(--k);color:#fff;display:flex;flex-direction:column;justify-content:space-between;gap:16px}.id.more p{color:var(--dmute)}
.id.more a{color:var(--l);font-weight:600;font-size:14.5px}
/* work */
.work{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.wk{border:1px solid var(--dline);border-radius:22px;background:var(--k);overflow:hidden}
.wk .pn{display:flex;justify-content:center;padding:44px 20px 0;height:430px;overflow:hidden;position:relative;background:radial-gradient(circle at 50% 100%,#1c1c20,#0c0c0e 70%)}
.wk .ph{--pw:240px;box-shadow:none;margin-top:0}
.wk .cp{position:absolute;top:16px;left:16px;font:600 11.5px Inter;padding:4px 11px;border-radius:99px;background:var(--l);color:var(--k);z-index:2}
.wk .bd{padding:24px;border-top:1px solid var(--dline)}.wk h3{font-size:19px;margin-bottom:8px;color:#fff}.wk p{font-size:15px}
.wk .tg{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.wk .tg span{font-size:12.5px;background:#1c1c20;color:#d8d8dc;padding:4px 10px;border-radius:99px}
.fine{margin-top:22px;font-size:14px}
/* tech */
.tk{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.tk div{border:1px solid var(--dline);border-radius:18px;padding:24px;background:var(--k)}
.tk h3{font-size:19px;color:var(--l);margin-bottom:8px}.tk p{font-size:14.5px}
/* support */
.sp{display:grid;grid-template-columns:1fr 1.4fr;gap:56px;align-items:start}
.sp .sh{margin:0}
.sl{border-top:1px solid var(--line)}
.sl div{padding:20px 0;border-bottom:1px solid var(--line);display:grid;grid-template-columns:.8fr 1.4fr;gap:24px}
.sl h3{font-size:17px}.sl p{color:var(--mute);font-size:15px}
/* faq */
.faq{max-width:780px}
details{border-top:1px solid var(--line);padding:20px 0}details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;font:600 18px Sora;list-style:none;display:flex;justify-content:space-between;gap:16px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";font-size:24px;line-height:1;transition:transform .2s}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--mute);max-width:640px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:96px 0}
.cta h2{font-size:clamp(34px,6vw,68px);letter-spacing:-.035em;max-width:800px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:520px;color:#2a3300}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.ft{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}
footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.hero .wrap,.sp{grid-template-columns:1fr}.stage{max-width:560px;width:100%;margin:0 auto}
.vals{grid-template-columns:repeat(2,1fr)}
.bento .s4{grid-column:span 6}.bento .s2{grid-column:span 3}
.jr{grid-template-columns:1fr;gap:22px}.st{display:grid;grid-template-columns:38px 1fr;column-gap:16px;padding:0}.st .dot{grid-row:span 2;margin:0}.st::after{display:none}.st h4{margin-top:2px}
.ind,.tk{grid-template-columns:repeat(2,1fr)}.work{grid-template-columns:1fr;max-width:520px}
.ft{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}}
/* mobile */
@media(max-width:600px){
section{padding:64px 0}.wrap{padding:0 20px}
.stage{height:auto;display:flex;justify-content:center;gap:12px}.stage .ph{position:static;--pw:158px;transform:none;margin:0}.p3{display:none}.p2{--pw:168px;margin-top:-18px}
.vals,.ind,.tk{grid-template-columns:1fr}.bento .s2,.bento .s4{grid-column:span 6}.bc{padding:24px}
.sl div{grid-template-columns:1fr;gap:6px}.ctas .btn{width:100%;justify-content:center}.ft{grid-template-columns:1fr}.wk .ph{--pw:220px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
